import java.util.ArrayList;
import java.util.List;

/**
 * A simple student manager with incomplete functionality.
 * Used for testing NaturalCC code completion and fixes.
 */
public class StudentManager {
    private List<Student> students;

    /**
     * Constructs an empty student manager.
     */
    public StudentManager() {
        this.students = new ArrayList<>();
    }

    /**
     * Adds a student with the given name and age.
     *
     * @param name the student's name (must not be null)
     * @param age  the student's age (must be positive)
     * @return true if the student was added successfully, false otherwise
     */
    // TODO: Complete this method - should add the student and return true on success
    public boolean addStudent(String name, int age) {
        if (name == null || age <= 0) {
            return false;
        }
        students.add(new Student(name, age));
        return true;
    }

    /**
     * Finds a student by name.
     *
     * @param name the name to search for
     * @return the Student object with the given name, or null if not found
     */
    // TODO: Complete this method - should find a student by name
    public Student findStudent(String name) {
        for (Student s : students) {
            if (s.getName().equals(name)) {
                return s;
            }
        }
        return null;
    }

    /**
     * Calculates the average age of all students.
     *
     * @return the average age, or 0.0 if there are no students
     */
    // BUG: Should check if the list is empty before calculating the average
    public double calculateAverageAge() {
        if (students.isEmpty()) {
            return 0.0;
        }
        int total = 0;
        for (Student s : students) {
            total += s.getAge();
        }
        return (double) total / students.size();
    }

    /**
     * Removes the first student with the given name.
     *
     * @param name the name of the student to remove
     */
    // BUG: Does not handle duplicate names
    public void removeStudent(String name) {
        for (int i = 0; i < students.size(); i++) {
            if (students.get(i).getName().equals(name)) {
                students.remove(i);
                break;
            }
        }
    }

    /**
     * Returns the number of currently managed students.
     *
     * @return the number of students
     */
    public int getStudentCount() {
        return students.size();
    }

    /**
     * Represents a student with a name and age.
     */
    public static class Student {
        private String name;
        private int age;

        /**
         * Constructs a student with the given name and age.
         *
         * @param name the student's name
         * @param age  the student's age
         */
        public Student(String name, int age) {
            this.name = name;
            this.age = age;
        }

        /**
         * Returns the student's name.
         *
         * @return the name
         */
        public String getName() { return name; }

        /**
         * 返回学生的年龄。
         *
         * @return 年龄
         */
        public int getAge() { return age; }

        /**
         * 设置学生的姓名。
         *
         * @param name 新姓名
         */
        public void setName(String name) { this.name = name; }

        /**
         * 设置学生的年龄。
         *
         * @param age 新年龄
         */
        public void setAge(int age) { this.age = age; }

        @Override
        public String toString() {
            return "Student{name='" + name + "', age=" + age + "}";
        }
    }

    /**
     * 用于演示的主方法。
     *
     * @param args 命令行参数（未使用）
     */
    public static void main(String[] args) {
        StudentManager manager = new StudentManager();
        manager.addStudent("Alice", 20);
        manager.addStudent("Bob", 22);
        System.out.println("Total students: " + manager.getStudentCount());
        System.out.println("Average age: " + manager.calculateAverageAge());
    }
}
